class SearchRequest {
  final EventKind kind;

  /// 天体英文名，如 "moon"。凌日时只用 `body_a`（"mercury"、"venus" 或空 = 两者）
  final String bodyA;
  final String bodyB;

  /// 起始年份（含），UTC 1 月 1 日
  final int fromYear;

  /// 结束年份（不含）
  final int toYear;

  /// 角距极小的上限（度）
  final double maxSeparationDeg;
  final ObserverInput? observer;
  final Lang lang;

  const SearchRequest({
    required this.kind,
    required this.bodyA,
    required this.bodyB,
    required this.fromYear,
    required this.toYear,
    required this.maxSeparationDeg,
    this.observer,
    required this.lang,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      bodyA.hashCode ^
      bodyB.hashCode ^
      fromYear.hashCode ^
      toYear.hashCode ^
      maxSeparationDeg.hashCode ^
      observer.hashCode ^
      lang.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchRequest &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          bodyA == other.bodyA &&
          bodyB == other.bodyB &&
          fromYear == other.fromYear &&
          toYear == other.toYear &&
          maxSeparationDeg == other.maxSeparationDeg &&
          observer == other.observer &&
          lang == other.lang;
}

/// 搜索过程中的一条回传。用普通结构体而不是带数据的枚举，Dart 端不需要 freezed。
class SearchUpdate {
  final UpdateKind kind;

  /// Progress：已完成比例 0–1
  final double fraction;

  /// Found：找到的事件
  final EventItem? item;

  /// Finished：事件总数
  final int count;

  /// Finished：是否被取消
  final bool cancelled;

  /// Finished：耗时（毫秒）
  final BigInt elapsedMs;

  const SearchUpdate({
    required this.kind,
    required this.fraction,
    this.item,
    required this.count,
    required this.cancelled,
    required this.elapsedMs,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      fraction.hashCode ^
      item.hashCode ^
      count.hashCode ^
      cancelled.hashCode ^
      elapsedMs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchUpdate &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          fraction == other.fraction &&
          item == other.item &&
          count == other.count &&
          cancelled == other.cancelled &&
          elapsedMs == other.elapsedMs;
}

