  final List<GeoPoint> centralLine;
  final Float64List pathWidthKm;
  final GeoPoint? greatestPoint;

  /// 全球最大食分栅格：第 0 行中心纬度 90 − step/2，第 0 列中心经度 −180 + step/2
  final double gridStepDeg;
  final int gridRows;
  final int gridCols;
  final Float32List grid;
