          runtimeType == other.runtimeType &&
          track == other.track &&
          greatest == other.greatest &&
          penumbraRadius == other.penumbraRadius &&
          umbraRadius == other.umbraRadius &&
          axisDeclinationDeg == other.axisDeclinationDeg;
}

